CREATE TABLE pb_schema_migrations(version INTEGER PRIMARY KEY, created_at INTEGER NOT NULL);
CREATE TABLE pb_templates(id TEXT PRIMARY KEY, title TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE pb_template_versions(id TEXT PRIMARY KEY, template_id TEXT NOT NULL REFERENCES pb_templates(id), version INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','published','inactive')), body TEXT NOT NULL, created_at INTEGER NOT NULL, created_by INTEGER REFERENCES staff(id), UNIQUE(template_id,version));
CREATE TRIGGER pb_template_immutable BEFORE UPDATE OF body ON pb_template_versions WHEN OLD.status<>'draft' BEGIN SELECT RAISE(ABORT,'immutable version'); END;
CREATE TABLE pb_questions(id TEXT NOT NULL, template_version TEXT NOT NULL REFERENCES pb_template_versions(id), dimension TEXT NOT NULL, title TEXT NOT NULL, position INTEGER NOT NULL, PRIMARY KEY(id,template_version));
CREATE TABLE pb_question_options(question_id TEXT NOT NULL, template_version TEXT NOT NULL, value INTEGER NOT NULL CHECK(value BETWEEN 1 AND 5), title TEXT NOT NULL, PRIMARY KEY(question_id,template_version,value), FOREIGN KEY(question_id,template_version) REFERENCES pb_questions(id,template_version));
CREATE TABLE pb_scoring_models(id TEXT PRIMARY KEY, version INTEGER NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('draft','published','inactive')), body TEXT NOT NULL, created_at INTEGER NOT NULL, created_by INTEGER REFERENCES staff(id));
CREATE TRIGGER pb_model_immutable BEFORE UPDATE OF body ON pb_scoring_models WHEN OLD.status<>'draft' BEGIN SELECT RAISE(ABORT,'immutable model'); END;
CREATE TABLE pb_request_limits(source_hash TEXT NOT NULL, action TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX pb_request_limits_lookup ON pb_request_limits(source_hash,action,created_at);
CREATE TABLE pb_sessions(owner_hash TEXT PRIMARY KEY, csrf TEXT NOT NULL, created_at INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE pb_assessments(id TEXT PRIMARY KEY, owner_hash TEXT NOT NULL REFERENCES pb_sessions(owner_hash), template_version TEXT NOT NULL REFERENCES pb_template_versions(id), scoring_version TEXT NOT NULL REFERENCES pb_scoring_models(id), question_order TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','completed')), stage INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, completed_at INTEGER, archived_at INTEGER);
CREATE INDEX pb_assessments_owner ON pb_assessments(owner_hash,created_at);
CREATE TABLE pb_answers(assessment_id TEXT NOT NULL REFERENCES pb_assessments(id) ON DELETE CASCADE, step INTEGER NOT NULL CHECK(step BETWEEN 1 AND 5), raw_json TEXT NOT NULL, normalized_json TEXT NOT NULL, elapsed_ms INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(assessment_id,step));
CREATE TABLE pb_question_metrics(assessment_id TEXT NOT NULL REFERENCES pb_assessments(id) ON DELETE CASCADE, question_id TEXT NOT NULL, elapsed_ms INTEGER NOT NULL CHECK(elapsed_ms BETWEEN 0 AND 86400000), updated_at INTEGER NOT NULL, PRIMARY KEY(assessment_id,question_id));
CREATE TABLE pb_evidence(id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL REFERENCES pb_assessments(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE pb_reports(id TEXT PRIMARY KEY, assessment_id TEXT NOT NULL UNIQUE REFERENCES pb_assessments(id) ON DELETE CASCADE, created_at INTEGER NOT NULL);
CREATE TABLE pb_report_versions(id TEXT PRIMARY KEY, report_id TEXT NOT NULL REFERENCES pb_reports(id) ON DELETE CASCADE, version INTEGER NOT NULL, scoring_version TEXT NOT NULL REFERENCES pb_scoring_models(id), body TEXT NOT NULL, input_json TEXT NOT NULL, reason TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(report_id,version));
CREATE TRIGGER pb_report_immutable BEFORE UPDATE ON pb_report_versions BEGIN SELECT RAISE(ABORT,'immutable report'); END;
CREATE TABLE pb_scores(report_version TEXT NOT NULL REFERENCES pb_report_versions(id) ON DELETE CASCADE, dimension TEXT NOT NULL, score REAL NOT NULL CHECK(score BETWEEN 0 AND 100), PRIMARY KEY(report_version,dimension));
CREATE TABLE pb_recommendations(id TEXT PRIMARY KEY, report_version TEXT NOT NULL REFERENCES pb_report_versions(id) ON DELETE CASCADE, dimension TEXT NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE pb_consents(id TEXT PRIMARY KEY, owner_hash TEXT NOT NULL REFERENCES pb_sessions(owner_hash), kind TEXT NOT NULL, text_version TEXT NOT NULL, policy_version TEXT NOT NULL, scope TEXT NOT NULL, purpose TEXT NOT NULL, created_at INTEGER NOT NULL, revoked_at INTEGER);
CREATE TABLE pb_oauth_states(state_hash TEXT PRIMARY KEY, owner_hash TEXT NOT NULL REFERENCES pb_sessions(owner_hash), consent_id TEXT NOT NULL REFERENCES pb_consents(id), expires INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE pb_instagram_connections(id TEXT PRIMARY KEY, owner_hash TEXT NOT NULL REFERENCES pb_sessions(owner_hash), account_id TEXT NOT NULL, username TEXT NOT NULL, token_cipher BLOB, scopes TEXT NOT NULL, granted_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('connected','disconnected','expired')), synced_at INTEGER, error_code TEXT, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX pb_instagram_active_owner ON pb_instagram_connections(owner_hash) WHERE status='connected';
CREATE TABLE pb_instagram_sync_jobs(id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES pb_instagram_connections(id) ON DELETE CASCADE, status TEXT NOT NULL, error_code TEXT, created_at INTEGER NOT NULL, completed_at INTEGER);
CREATE TABLE pb_instagram_profiles(id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES pb_instagram_connections(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE pb_instagram_media(id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES pb_instagram_connections(id) ON DELETE CASCADE, external_id TEXT NOT NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE pb_instagram_analysis(id TEXT PRIMARY KEY, connection_id TEXT NOT NULL REFERENCES pb_instagram_connections(id) ON DELETE CASCADE, body TEXT NOT NULL, version TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE pb_events(id TEXT PRIMARY KEY, owner_hash TEXT NOT NULL, assessment_id TEXT, event TEXT NOT NULL, template_version TEXT, stage INTEGER, context_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL, dedupe_key TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE INDEX pb_events_time ON pb_events(event,created_at);
CREATE TABLE pb_audit(id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT NOT NULL, context_json TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL);
CREATE TRIGGER pb_audit_no_update BEFORE UPDATE ON pb_audit BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER pb_audit_no_delete BEFORE DELETE ON pb_audit BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TABLE pb_deletion_requests(id TEXT PRIMARY KEY, owner_hash TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, completed_at INTEGER);
CREATE TABLE pb_privacy_settings(id INTEGER PRIMARY KEY CHECK(id=1), retention_days INTEGER NOT NULL CHECK(retention_days BETWEEN 1 AND 365), updated_at INTEGER NOT NULL);
CREATE TABLE pb_expert_feedback(id TEXT PRIMARY KEY, template_version TEXT NOT NULL REFERENCES pb_template_versions(id), actor_id INTEGER NOT NULL REFERENCES staff(id), body TEXT NOT NULL, created_at INTEGER NOT NULL);
INSERT INTO pb_privacy_settings VALUES(1,30,strftime('%s','now'));
INSERT INTO pb_schema_migrations VALUES(1,strftime('%s','now'));
